/* Resource and cost interaction design; all amounts are synthetic demo data. */
(()=>{
const B=(s,a,k='',c='')=>`<button class="btn ${c}" data-cost="${a}" data-key="${esc(k)}">${s}</button>`;
S.cost=S.cost||{budget:10000,threshold:80,concurrency:4,rate:2,version:1,history:[],limits:{}};
const d=S.cost,money=n=>'¥'+Number(n).toFixed(2),F=(s,id,v)=>field(s,`<input class="input" type="number" min="0" id="${id}" value="${v}">`);
function task(){return demandCurrent()}
function estimate(t){return Math.max(10,(t?.deps?.length||5)*2)*d.rate}
function records(){return S.runs.map(r=>({id:r.id,task:r.taskId||'历史模板任务',version:r.costVersion||1,confirmed:r.costConfirmed||0,pending:r.costPending??6.4,run:r}))}
function totals(){const rr=records();return {confirmed:rr.reduce((a,r)=>a+r.confirmed,0),pending:rr.reduce((a,r)=>a+r.pending,0),reserved:Object.values(d.limits).filter(x=>x.reserved).reduce((a,x)=>a+x.limit,0)}}
function status(){const x=totals();return `<div class="notice">合成费用演示 · 单价非真实报价 · 浏览器内保存。预算与资源配额分别校验；正式系统由服务端计量和控制。</div><div class="grid4 mt mb">${stat('周期预算',money(d.budget),'项目预算；外部支出与内部核算分列','chart')}${stat('已确认',money(x.confirmed),'已完成用量与计价对账','check')}${stat('暂计 / 预留',money(x.pending)+' / '+money(x.reserved),'在途费用尚未结清','clock')}${stat('可用预算',money(d.budget-x.confirmed-x.pending-x.reserved),'周期预算 − 已确认 − 暂计 − 预留','chart')}</div>`}
function config(t){const c=d.limits[t.id]||{limit:100};return section('资源与预算',`<div class="pad stack"><div class="between"><div><b>预计 ${money(estimate(t))}</b><p class="small muted">按当前依赖数量推算的交互样例；含被测调用、裁判和执行资源。计价 v${d.version}。</p></div>${B('配置资源与预算','config',t.id)}</div><div class="kv"><dt>本次费用上限</dt><dd>${money(c.limit)}</dd><dt>预算状态</dt><dd>${esc(c.state||'尚未预检')} ${c.reserved?'· 已预留':''}</dd><dt>达到上限</dt><dd>停止新工作，核清在途调用；可能存在延迟计费尾差。</dd></div><div class="flex wrap">${B('预算预检与预留','reserve',t.id,'primary')}${B('取消预留并对账','release',t.id)}${B('项目配额与预算','project')}</div></div>`)}
const oldTask=pages.task;pages.task=()=>oldTask()+(task()?config(task()):'');
const oldRun=pages.run;pages.run=()=>oldRun()+section('费用明细',`<div class="pad stack">${notice('金额为合成演示；费用确认不改变质量结论。部分执行必须单列未完成范围。')}${B('查看当前运行费用','detail',S.runId||S.runs[0]?.id||'')} ${B('项目费用汇总','ledger')}</div>`);
const oldResources=pages.resources;pages.resources=()=>head('资源、接入与成本','资源管理、项目预算和计价配置共用现有平台管理入口。',B('项目配额与预算','project')+B('计价规则','rates')+B('费用台账','ledger'))+status()+oldResources();
function project(){modal('项目设置 · 配额与预算',`<div class="stack">${status()}${F('项目周期预算（人民币）','cost-budget',d.budget)}${F('预警阈值（%）','cost-threshold',d.threshold)}${F('执行并发上限','cost-concurrency',d.concurrency)}<p class="small muted">周期：当前演示周期。项目负责人（质量负责人演示角色）可修改预算；运维可修改资源配额。保存立即生效并记录修改人和时间。</p></div>`,B('关闭','close')+B('保存配置','save-project','','primary'),true)}
function rates(){modal('平台管理 · 计价规则',`<div class="stack">${notice('内部核算与外部支出分别展示；不处理采购、付款或财务结算。')}${F('模型调用演示费率（元 / 计费单位）','cost-rate',d.rate)}${table(['类别','计量依据','计价状态'],[['被测 / 裁判调用','Token / 服务商计费量','演示费率 v'+d.version],['执行 / 设备','规格 × 占用时长','内部核算；样例'],['存储','容量 × 保留时间','用量已记录，待计价'],['人工复核','确认的有效工时','仅统计工时，待费率确认']])}<p>保存创建新计价版本；历史运行保留原版本。未来才生效的规则应配置生效时间；本演示立即生效。</p>${table(['时间','操作者','修改'],d.history.map(h=>[h.at,h.actor,h.text]))}</div>`,B('关闭','close')+B('保存新计价版本','save-rates','','primary'),true)}
function ledger(){modal('项目费用台账',`<div class="stack">${status()}${records().length?table(['运行 / 任务','计价版本','已确认','暂计','操作'],records().map(r=>[esc(r.id+' / '+r.task),'v'+r.version,money(r.confirmed),money(r.pending),B('明细','detail',r.id)])):'<div class="empty">尚无运行记录。创建评测并完成运行后在此查看费用。</div>'}${B('导出费用明细','export')}<p class="small muted">存储费用按保留周期持续发生，未包含在运行结束费用中。不同核算类型不能混为外部账单。</p></div>`,B('关闭','close'),true)}
function detail(id){const r=S.runs.find(x=>x.id===id);if(!r)return toast('尚无运行记录，请先完成一次评测。','error');modal('运行费用 · '+esc(id),`<div class="stack"><div class="notice warn">${r.costPending===0?'费用已完成演示对账':'暂计费用 ¥6.40，另有存储待计价；不表示最终账单。'}</div>${table(['费用项目','核算类别','用量依据','金额 / 状态'],[['被测调用','外部支出','合成计费量 × 固定单价','¥3.20'],['裁判调用','外部支出','合成计费量 × 固定单价','¥1.60'],['执行资源','内部核算','合成占用时长','¥1.00'],['技术重试 / 恢复','外部支出','独立 attempt 记录','¥0.60'],['存储','内部核算','0.2 GB；保留期待确认','待计价'],['人工复核','内部核算','尚未确认工时','待确认']])}<div class="kv"><dt>计价版本</dt><dd>v${r.costVersion||1}；修改当前单价不回算历史</dd><dt>费用归集</dt><dd>${esc(r.taskId||'历史模板任务')} / ${esc(r.id)}</dd><dt>对账依据</dt><dd>演示账单事件；相同事件标识重复确认不重复计费</dd></div>${B('确认已知用量费用（演示）','settle',id)}<p class="small muted">该动作只确认已知的 ¥6.40；存储和人工缺口仍保留。费用状态与执行状态、质量结论独立。</p></div>`,B('关闭','close'),true)}
function history(text){d.history.unshift({at:new Date().toLocaleString('zh-CN'),actor:roleNames[S.role],text});save()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-cost]');if(!b)return;const a=b.dataset.cost,k=b.dataset.key;try{if(['save-project','save-rates','save-limit','reserve','release','settle'].includes(a))throw Error('旧费用演示只读；新流程由系统按批准价格自动处理。');
if(a==='close')return close();if(a==='project')return project();if(a==='rates')return rates();if(a==='ledger')return ledger();if(a==='detail')return detail(k);
if(a==='config'){const t=task(),c=d.limits[k]||{limit:100};return modal('任务 · 资源与预算',`<div class="stack">${F('本次费用上限（人民币）','cost-limit',c.limit)}<p>预估 ${money(estimate(t))}；默认最多并发 ${d.concurrency}。修改后原预算预检失效，须重新预留。</p>${notice('费用上限不替代原任务的演示点数准入。当前为新增成本交互设计，真实运行须由服务端统一执行预算策略。')}</div>`,B('关闭','close')+B('保存任务预算','save-limit',k,'primary'))}
if(a==='save-project'){if(!guard(['quality','ops']))return;const budget=Number($('#cost-budget').value),threshold=Number($('#cost-threshold').value),concurrency=Number($('#cost-concurrency').value);if(!Number.isFinite(budget)||budget<0||threshold<=0||threshold>100||!Number.isInteger(concurrency)||concurrency<1)throw Error('请填写有效预算、1–100%的阈值和正整数并发数');if(S.role==='quality')d.budget=budget;if(S.role==='ops')d.concurrency=concurrency;d.threshold=threshold;history('保存项目预算 / 配额');close();render();return toast('已保存当前角色可修改的配置','success')}
if(a==='save-rates'){if(!guard('ops'))return;const n=Number($('#cost-rate').value);if(!Number.isFinite(n)||n<=0)throw Error('单价须大于零');d.rate=n;d.version++;history('发布计价规则 v'+d.version);close();render();return toast('新计价版本已保存','success')}
if(a==='save-limit'){if(!guard('engineer'))return;const n=Number($('#cost-limit').value);if(!Number.isFinite(n)||n<=0)throw Error('费用上限须大于零');if(d.limits[k]?.reserved)throw Error('先取消原预算预留并完成对账，再修改上限');d.limits[k]={limit:n,state:'配置已保存，待预检',reserved:false};history('保存任务费用上限 '+k);close();render();return}
if(a==='reserve'){const t=task(),c=d.limits[k]||(d.limits[k]={limit:100});if(c.reserved)return toast('已存在预算预留，未重复占用');const x=totals(),available=d.budget-x.confirmed-x.pending-x.reserved;if(c.limit<estimate(t)||available<c.limit){c.state='预算不足：调整配置或申请追加';save();render();return}c.reserved=true;c.version=d.version;c.state='预算预检通过（费用演示）';history('预留任务预算 '+k);render();return}
if(a==='release'){const c=d.limits[k];if(c){c.reserved=false;c.state='预留已释放；已有运行费用须另行对账';history('释放尚未派发的预算预留 '+k);render()}return}
if(a==='settle'){const r=S.runs.find(x=>x.id===k);if(r.costSettledEvent===k+'-usage')return toast('相同计费事件已确认，未重复计费');r.costSettledEvent=k+'-usage';r.costConfirmed=6.4;r.costPending=0;r.costVersion=r.costVersion||1;history('确认已知用量费用 '+k);detail(k);return}
if(a==='export'){const blob=new Blob([JSON.stringify({demo:true,currency:'CNY',records:records().map(({run,...x})=>x),unpriced:['storage','human']},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='evaluation-cost-demo.json';link.click();URL.revokeObjectURL(u)}
}catch(err){toast(err.message,'error')}});
render();
})();
